import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            m = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(n + 1)]

        for _ in range(m):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)

        visited = [False] * (n + 1)
        stack = [1]
        visited[1] = True
        component = []

        while stack:
            node = stack.pop()
            component.append(node)
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)

        jury = set(component)
        contestants = []

        for i in range(1, n + 1):
            if i not in jury:
                contestants.append(i)

        if not jury or not contestants:
            out_lines.append("No")
        else:
            out_lines.append("Yes")
            out_lines.append(f"{len(jury)} {len(contestants)}")
            out_lines.append(" ".join(map(str, sorted(jury))))
            out_lines.append(" ".join(map(str, sorted(contestants))))

    sys.stdout.write("\n".join(out_lines) + "\n")

if __name__ == "__main__":
    solve()
